def pricing_html() -> str:
    """Public Beta pricing: a single free plan, no paid checkout links."""
    return ('''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Lucas is free during Beta."><title>Lucas Beta — Free During Testing</title><style>body{margin:0;background:#080c18;color:#f6f8ff;font:16px/1.6 system-ui,sans-serif}nav{display:flex;justify-content:space-between;align-items:center;padding:24px 6%;border-bottom:1px solid #263047}a{color:inherit;text-decoration:none}main{max-width:680px;margin:75px auto;padding:0 22px;text-align:center}h1{font-size:clamp(36px,6vw,60px);line-height:1.1}.card{background:#141c30;border:1px solid #334363;border-radius:20px;padding:34px;text-align:left}.price{font-size:46px;font-weight:800}.cta{display:block;background:#6473f4;color:white;padding:14px;text-align:center;border-radius:10px;font-weight:700}li{margin:10px 0}.muted{color:#b5c0d8}</style></head><body><nav><a href="/">Lucas</a><a href="/dashboard">Sign in</a></nav><main><h1>Free during Beta</h1><p class="muted">Lucas is free to use while we test and improve the product. Plans and limits may change after Beta.</p><section class="card"><h2>Lucas Beta</h2><div class="price">$0 <small style="font-size:16px">/ month</small></div><ul><li>100,000 Operations per month</li><li>3 Computers</li><li>3 AI accounts</li><li>Multiple concurrent tasks</li><li>Full Lucas execution</li><li>No additional Lucas token fees</li></ul><a class="cta" href="/dashboard">Start Free Beta</a></section></main></body></html>''').replace('<head>', '<head>'+TRACKING_HEAD, 1)


